from PIL import Image

def blobs(path):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    ys=[]
    mask = [[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b = px[x,y]
            if r>180 and g>150 and b<100:
                mask[y][x]=True
                ys.append((x,y))
    visited=set(); out=[]
    for x,y in ys:
        if (x,y) in visited: continue
        stack=[(x,y)]; visited.add((x,y)); cells=[(x,y)]
        while stack:
            cx,cy=stack.pop()
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and mask[ny][nx] and (nx,ny) not in visited:
                        visited.add((nx,ny)); stack.append((nx,ny)); cells.append((nx,ny))
        if len(cells)>8:
            mx=sum(c[0] for c in cells)/len(cells)
            my=sum(c[1] for c in cells)/len(cells)
            out.append((len(cells), round(mx,1), round(my,1)))
    return sorted(out, key=lambda t:(t[2],t[1]))

